<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import { getApiError } from '../api/http'
const auth = useAuthStore(); const router = useRouter(); const form = reactive({ email: '', password: '' }); const error = ref(''); const loading = ref(false)
async function submit() { error.value = ''; loading.value = true; try { await auth.login(form); await router.replace({ name: 'dashboard' }) } catch (cause) { error.value = getApiError(cause, 'Не удалось войти. Попробуйте ещё раз.') } finally { loading.value = false } }
</script>
<template><main class="flex min-h-screen items-center justify-center bg-slate-950 px-4 py-12"><section class="w-full max-w-md rounded-3xl bg-white p-8 shadow-2xl shadow-black/20 sm:p-10"><p class="text-sm font-semibold uppercase tracking-[0.2em] text-indigo-600">Realtime chat</p><h1 class="mt-3 text-3xl font-bold tracking-tight text-slate-900">С возвращением</h1><p class="mt-2 text-sm text-slate-500">Войдите, чтобы продолжить общение.</p><form class="mt-8 space-y-5" @submit.prevent="submit"><label class="block text-sm font-medium text-slate-700">Email<input v-model.trim="form.email" required type="email" autocomplete="email" class="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100" placeholder="you@example.com" /></label><label class="block text-sm font-medium text-slate-700">Пароль<input v-model="form.password" required type="password" autocomplete="current-password" class="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100" placeholder="Ваш пароль" /></label><p v-if="error" role="alert" class="rounded-xl bg-rose-50 px-4 py-3 text-sm text-rose-700">{{ error }}</p><button :disabled="loading" class="w-full rounded-xl bg-indigo-600 px-4 py-3 font-semibold text-white hover:bg-indigo-700 disabled:opacity-60">{{ loading ? 'Входим…' : 'Войти' }}</button></form><p class="mt-6 text-center text-sm text-slate-500">Нет аккаунта? <RouterLink class="font-semibold text-indigo-600" :to="{ name: 'register' }">Зарегистрироваться</RouterLink></p></section></main></template>
